// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MultiplicatorX4 c;
    Recorder rec;

    function setUp() public {
        c = new MultiplicatorX4();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 extra, uint256 v, bytes memory data) public {
        vm.assume(extra <= VALUE_CAP);
        vm.assume(v <= VALUE_CAP);
        extra = bound(extra, 1, 1e18);
        v = bound(v, 0, 1e18);
        vm.assume(data.length <= 32);

        // pre-fund c so its stored balance and the sent value can differ
        vm.deal(address(this), extra + v);
        (bool ok, ) = payable(address(c)).call{value: extra}("");
        assertTrue(ok, "funding c failed");

        vm.prank(address(this)); // owner of c
        c.Command{value: v}(address(rec), data);

        // Rule: the callee receives exactly the value sent with Command (v),
        // regardless of how much ether c already held.
        assertTrue(rec.lastValue() == v, "callee must receive exactly msg.value");
    }
}

contract Recorder {
    uint256 public lastValue;
    uint256 public calls;

    fallback() external payable {
        lastValue = msg.value;
        calls++;
    }

    receive() external payable {
        lastValue = msg.value;
        calls++;
    }
}
